import fs from "node:fs";
import { Router } from "express";
import { CebuArea } from "./generated/prisma/enums";

// The Cebu location directory (region -> city/municipality -> barangay, with official PSGC codes).
// Source of truth: backend/data/cebu-locations.json, generated by `npm run locations:build`.
// It is read once at startup and never written by the app, so there is nothing for a request to modify:
// updating the directory is a code change (rebuild the file, redeploy). The read endpoints below sit under
// /api/admin, so only a logged-in admin can call them.

type Region = { key: string; label: string; localityCodes: string[] };
type Locality = { code: string; name: string; officialName: string; type: "city" | "municipality"; regionKey: string; barangayCount: number };
type Directory = {
  meta: { psgcPublication: string; counts: { regions: number; localities: number; barangays: number } };
  regions: Region[];
  localities: Locality[];
  barangays: Record<string, [code: string, name: string][]>;
};

const directory: Directory = JSON.parse(fs.readFileSync(new URL("../data/cebu-locations.json", import.meta.url), "utf8"));

const regionByKey = new Map(directory.regions.map((r) => [r.key, r]));
const localityByCode = new Map(directory.localities.map((l) => [l.code, l]));
const barangayNames = new Map<string, Map<string, string>>(
  Object.entries(directory.barangays).map(([localityCode, rows]) => [localityCode, new Map(rows)]),
);

// Same normalisation the directory builder uses: "City of Bogo", "Bogo City" and "bogo" all become "bogo".
const norm = (s: string) =>
  s
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/^city of /, "")
    .replace(/ city$/, "")
    .replace(/[^a-z0-9]/g, "");

export type ResolvedLocation = {
  region: string;
  cityCode: string;
  city: string; // display name, e.g. "Talisay City" (kept in Property.city for the public site)
  area: CebuArea | null; // NORTH / SOUTH only for the two regions the public filters know about
  barangay: string | null;
  barangayCode: string | null;
};

const AREA_FOR_REGION: Record<string, CebuArea> = { NORTH_CEBU: CebuArea.NORTH, SOUTH_CEBU: CebuArea.SOUTH };

// Checks that region, city and barangay all exist AND belong to each other, and returns the values to store.
// Everything stored is taken from the directory, never from what the browser said the names are.
export function resolveLocation(input: {
  region: unknown;
  cityCode: unknown;
  barangayCode: unknown;
}): { ok: true; value: ResolvedLocation } | { ok: false; error: string } {
  const { region, cityCode, barangayCode } = input;
  if (typeof region !== "string" || !regionByKey.has(region)) return { ok: false, error: "Choose a valid region" };
  if (typeof cityCode !== "string" || !localityByCode.has(cityCode)) return { ok: false, error: "Choose a valid city or municipality" };
  const locality = localityByCode.get(cityCode)!;
  if (locality.regionKey !== region) return { ok: false, error: `${locality.name} is not in ${regionByKey.get(region)!.label}` };

  let barangay: string | null = null;
  let code: string | null = null;
  if (barangayCode !== null && barangayCode !== undefined && barangayCode !== "") {
    const name = typeof barangayCode === "string" ? barangayNames.get(cityCode)?.get(barangayCode) : undefined;
    if (!name) return { ok: false, error: `Choose a barangay that belongs to ${locality.name}` };
    barangay = name;
    code = barangayCode as string;
  }
  return { ok: true, value: { region, cityCode, city: locality.name, area: AREA_FOR_REGION[region] ?? null, barangay, barangayCode: code } };
}

// Best-effort match of an older listing's free-text city (e.g. "Carcar", "talisay city") to a directory entry.
// Returns null unless exactly one locality matches, so nothing is ever guessed.
export function matchLegacyCity(city: string): { region: string; cityCode: string } | null {
  const head = city.split(",")[0]?.trim() ?? "";
  const key = norm(head);
  if (!key) return null;
  const hits = directory.localities.filter((l) => norm(l.name) === key || norm(l.officialName) === key);
  return hits.length === 1 ? { region: hits[0].regionKey, cityCode: hits[0].code } : null;
}

// ---- Read-only endpoints, mounted at /api/admin/locations (admin login already enforced there) -------------
export const locationsRouter = Router();

// GET /api/admin/locations/regions
locationsRouter.get("/regions", (_req, res) => {
  res.json({
    data: directory.regions.map((r) => ({ key: r.key, label: r.label, localityCount: r.localityCodes.length })),
    meta: { psgcPublication: directory.meta.psgcPublication },
  });
});

// GET /api/admin/locations/localities?region=SOUTH_CEBU
locationsRouter.get("/localities", (req, res) => {
  const region = typeof req.query.region === "string" ? regionByKey.get(req.query.region) : undefined;
  if (!region) return res.status(400).json({ error: "region must be one of the listed regions" });
  const data = region.localityCodes
    .map((code) => localityByCode.get(code)!)
    .map((l) => ({ code: l.code, name: l.name, type: l.type }))
    .sort((a, b) => a.name.localeCompare(b.name, "en", { sensitivity: "base" }));
  res.json({ data });
});

// GET /api/admin/locations/barangays?city=0702250000
locationsRouter.get("/barangays", (req, res) => {
  const rows = typeof req.query.city === "string" ? directory.barangays[req.query.city] : undefined;
  if (!rows) return res.status(400).json({ error: "city must be the code of a listed city or municipality" });
  res.json({ data: rows.map(([code, name]) => ({ code, name })) });
});

// GET /api/admin/locations/match?city=Carcar  ->  { data: { region, cityCode } | null }
// Lets the edit form pre-fill region and city for listings saved before the selector existed.
locationsRouter.get("/match", (req, res) => {
  const city = typeof req.query.city === "string" ? req.query.city.slice(0, 120) : "";
  res.json({ data: matchLegacyCity(city) });
});
